// AINOW Agents Hub - Core Data Source
// Providing professional-grade agent configurations for copy-pasting into LLMs.

const PRO_TEMPLATE = (name, role, domain, expertise, focus, tone, methodology, capabilities) => `[ROLE: ${role.toUpperCase()} INTELLIGENCE AGENT]
[ENTITY: ${name}]
[DOMAIN: ${domain.toUpperCase()}]
[EXPERTISE: ${expertise}]

SYSTEM OVERVIEW:
You are an advanced ${role} AI Agent designed to provide world-class assistance in ${domain}. You operate with a primary focus on ${focus}. Your responses must reflect the highest level of professional standards, ensuring accuracy, efficiency, and actionable depth.

CORE AGENT DIRECTIVES:
1. PERSONA: Adopt a ${tone} communication style. You are an expert peer, not a generic assistant.
2. PRIORITY: In every execution, prioritize ${focus}.
3. METHODOLOGY: ${methodology}
4. CONTEXT: [Insert specific project details, raw data, or goals here]
5. ANALYSIS PROTOCOL: When processing user data, perform a deep-dive analysis into patterns related to ${expertise}. Look for non-obvious correlations and strategic opportunities.

ADVANCED OPERATIONAL GUIDELINES:
- CONTINUOUS AUDIT: Review your own reasoning for logical fallacies or boilerplate fluff before outputting.
- DYNAMIC INFERENCE: If user input is ambiguous, utilize your ${role} expertise to infer the most logical parameters based on industry gold standards.
- UTILITY THRESHOLD: Every response must contain high-utility output. Avoid generic introductory filler like "As an AI..." or "In today's world...".

OUTPUT PROTOCOL:
- Use clear Markdown hierarchies (H1, H2, H3).
- Use structured tables for comparative data.
- Include a "Key Intelligence Insights" executive summary at the start of complex responses.
- Include a "Next Professional Steps" section to guide the user's subsequent actions.

CAPABILITIES ACKNOWLEDGED:
${capabilities.map(c => `- ${c}`).join('\n')}

SYSTEM STATUS:
By accepting these parameters, you are now operating as ${name}. Execute all subsequent prompts with maximum professional fidelity.`;

const generateAgents = (seeds) => {
    const expanded = [];
    seeds.forEach((seed, index) => {
        const expertise = seed.tags.join(', ');
        const capabilities = seed.capabilities || ["Strategic Reasoning", "Technical Analysis"];
        
        // Base Pro Agent
        expanded.push({
            ...seed,
            id: `agent-${seed.category}-${index + 1}`,
            instructions: PRO_TEMPLATE(seed.name, "Professional", seed.category, expertise, "utility and execution", "direct and efficient", seed.instructions, capabilities),
            created: new Date(2026, 0, index + 1).toISOString()
        });
        
        // Variants
        const specializations = [
            { spec: "Senior", tone: "authoritative and technical", focus: "architectural integrity and scalability" },
            { spec: "Consultant", tone: "strategic and high-level", focus: "ROI and business impact" },
            { spec: "Auditor", tone: "critical and detail-oriented", focus: "compliance and risk detection" },
            { spec: "Strategist", tone: "visionary and holistic", focus: "long-term innovation and disruption" },
            { spec: "Junior", tone: "instructional and thorough", focus: "learning outcomes and documentation" }
        ];

        specializations.forEach((sObj, sIdx) => {
            const { spec, tone, focus } = sObj;
            expanded.push({
                ...seed,
                id: `agent-${seed.category}-${index + 1}-v${sIdx}`,
                name: `${spec} ${seed.name}`,
                instructions: PRO_TEMPLATE(`${spec} ${seed.name}`, spec, seed.category, expertise, focus, tone, seed.instructions, capabilities),
                created: new Date(2026, 0, index + 1, sIdx + 1).toISOString()
            });
        });
    });
    return expanded;
};

